+        if (result != null) {
+            if (result.length == 1) {
+                return result[0];
+            } else {
+                return Character.ERROR;
+            }
+        } else {
+            // default to Character class' one
+            return Character.toLowerCase(src.codePointAt(index));
+        }
+    }
