+            ch = src.codePointAt(i);
+            cc = Normalizer.getCombiningClass(ch);
+
+            if (cc == COMBINING_CLASS_ABOVE) {
+                return true;
+            } else if (cc == 0) {
+                return false;
+            }
+        }
+
+        return false;
+    }
